import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
C=[['拉丁 cutis','皮肤']]
CT=C+[['学术拉丁 cutaneus → 英语 cutaneous','与皮肤有关的']]
S=C+[['sub- 在下 + cut- 皮肤','形成“皮下”的构词'],['英语 subcutaneous','可按 sub- + cutaneous 分析；另有拉丁 subcutaneus 借入分析']]
W=[E('cutaneous','/kjuːˈteɪniəs/','皮肤的；与皮肤有关的〔医学〕','看到这个词，先把注意力放到皮肤这一层。','借学术拉丁 cutaneus，来自拉丁 cutis“皮肤”。现代 cutane- 表示皮肤，-ous 为形容词形式；这里的 cut 不是英语“切割”。',CT,'Cutaneous sensation 是皮肤感觉，cutaneous symptoms 是表现在皮肤上的症状。它只是说明与皮肤有关，不意味着一定有伤口，也不等于某一种病名。','cutaneous sensation；cutaneous nerves；cutaneous symptoms；a cutaneous reaction。','skin 是日常说法；cutaneous 是常见的医学形容词。Subcutaneous 多了 sub-，指皮肤下面。',('The textbook describes the nerves involved in cutaneous sensation.','课本介绍了参与皮肤感觉的神经。'),('The report lists the cutaneous symptoms separately from the other findings.','报告把皮肤症状与其他发现分开列出。'),sources=['https://www.merriam-webster.com/dictionary/cutaneous','https://www.etymonline.com/word/cutaneous']),
E('subcutaneous','/ˌsʌbkjuˈteɪniəs/','皮下的〔医学〕','不是涂在表面，而是在皮肤下面那一层。','现代可清楚拆成 sub-“下面” + cutaneous“皮肤的”。词源资料也有直接接拉丁 subcutaneus 的分析，两者都回到 cutis“皮肤”，不影响“皮下”这一核心意思。',S,'Subcutaneous fat 是皮下脂肪，subcutaneous tissue 是皮下组织。它描述所在位置；在给药语境中，则说明药物送入皮下组织，而不是说所有进入身体的注射都叫这个。','subcutaneous fat/tissue；a subcutaneous injection；the subcutaneous layer。','cutaneous 是与皮肤有关；subcutaneous 明确在皮下。Intravenous 是静脉内，不能当作同一种位置。',('The diagram shows a layer of subcutaneous fat beneath the skin.','示意图显示了皮肤下面的一层皮下脂肪。'),('The anatomy model separates the skin from the subcutaneous tissue.','解剖模型把皮肤与皮下组织分开展示。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/subcutaneous','https://www.etymonline.com/word/subcutaneous','https://en.wiktionary.org/wiki/subcutaneous']),
E('cuticle','/ˈkjuːtɪkəl/','指甲根部的角质皮；表面保护层','像覆盖在外面的一层薄皮。','借拉丁 cuticula，是 cutis“皮肤”的指小形式，字面上是“小皮、薄皮”。现代后半 -icle 可以帮助记小的东西，但不是英语 cut“剪” + 一个动作后缀。',C+[['拉丁 cuticula → 英语 cuticle','薄皮 → 指甲边角质皮及生物体表的保护层']],'日常最常见的是指甲根部那圈角质皮。生物课里还会遇到植物叶片的蜡质 cuticle、昆虫体表的 cuticle；这些是相应生物的外层保护结构，不是长在人类指甲上的同一块组织。','dry cuticles；the cuticle around a nail；a waxy cuticle；the insect cuticle。','nail 是指甲本身；cuticle 在日常语境中指其根部的角质皮。科学文章里的 cuticle 要根据植物或动物对象来译。',('The close-up photograph shows the cuticle at the base of the nail.','特写照片显示了指甲根部的角质皮。'),('A waxy cuticle helps the leaf reduce water loss.','一层蜡质保护层帮助叶片减少水分流失。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/cuticle','https://www.etymonline.com/word/cuticle','https://www.merriam-webster.com/dictionary/cuticle']),
E('subcutaneously','/ˌsʌbkjuˈteɪniəsli/','在皮下；以皮下方式〔医学〕','它回答的是“放在哪里、通过哪一层”，答案是皮肤下面。','英语 subcutaneous + -ly，变成副词；sub-“下面”与皮肤 cutis 的关系不变。',S+[['英语 subcutaneous + -ly → subcutaneously','在皮下；以皮下方式']],'它常跟 administered、injected 或 implanted 搭配，说明某项操作的位置或方式。把名词前的 subcutaneous injection 换成完整句子时，可以说 administered subcutaneously。','administered/injected subcutaneously；implanted subcutaneously。','subcutaneous 放在名词前说明性质，subcutaneously 修饰动作；两者的区别是词性，不是两种不同的身体部位。',('The study recorded whether the medication was administered subcutaneously.','研究记录了药物是否以皮下方式给予。'),('The device was implanted subcutaneously, according to the procedure report.','操作报告记载，这个装置被植入了皮下。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/subcutaneously','https://en.wiktionary.org/wiki/subcutaneously'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C0292');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C0292');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：更细分的皮肤解剖、植物化学或给药术语。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C0292',meaning='皮肤',core='cut- 在这组里是一层皮肤，不是刀剪的动作。',image='cutaneous 说皮肤本身；subcutaneous 指皮肤下面；cuticle 是表面一层薄皮或保护层。',intro='保留一般医学阅读和生物课中常见的四个词。先看部位，再看词性，就不会把“皮肤的”和“皮下的”混在一起。',forms='拉丁 cutis“皮肤”；cutane- 用于皮肤形容词，cuticula 是其指小形式。',branches=[['与皮肤有关','cutaneous'],['皮肤下面','subcutaneous、subcutaneously'],['薄皮与保护层','cuticle']],contrasts='这组并非来自英语 cut“切割”。Cuticle 的生物学含义比指甲边的角质皮宽，要结合对象理解。',practice='分别说出 cutaneous、subcutaneous 指的范围，再把 subcutaneous injection 改写成带 subcutaneously 的句子。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.merriam-webster.com/dictionary/cutaneous','https://www.etymonline.com/word/subcutaneous','https://www.etymonline.com/word/cuticle'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_220_cut.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0292',len(W),'new')
